// ---- word puzzles: lists worked out from the word list itself (W), so they grow when it does
(function(){
  var all=[],tier={};for(var t=5;t>=1;t--){var ws=String(W[t]||'').split(/\s+/);for(var i=0;i<ws.length;i++){var w=ws[i];if(w&&!tier[w]){tier[w]=t;all.push(w)}}}
  function WL(name,test,min){var out=[];for(var i=0;i<all.length;i++){var w=all[i];if(tier[w]>=(min||1)&&test(w))out.push(w+':'+tier[w])}L[name]=out.join(';')}
  var VOW=/[aeiou]/g;
  WL('w_allvowels',function(w){return /a/.test(w)&&/e/.test(w)&&/i/.test(w)&&/o/.test(w)&&/u/.test(w)});
  WL('w_novowels',function(w){return w.length>=3&&!/[aeiou]/.test(w)});
  WL('w_samefl',function(w){return w.length>=5&&w[0]===w[w.length-1]},2);
  WL('w_twodoubles',function(w){var m=w.match(/([a-z])\1/g);return !!m&&m.length>=2});
  WL('w_alpha',function(w){if(w.length<5)return false;for(var i=1;i<w.length;i++)if(w[i]<w[i-1])return false;return true});
  WL('w_toprow',function(w){return w.length>=5&&/^[qwertyuiop]+$/.test(w)});
  WL('w_backwards',function(w){if(w.length<4)return false;var r=w.split('').reverse().join('');return r!==w&&!!tier[r]});
  WL('w_onlye',function(w){var v=w.match(VOW);return !!v&&v.length>=3&&!/[aiou]/.test(w)},2);
  WL('w_animal',function(w){return w.length>=5&&/cat|dog|ant|rat|bat|owl|hen|pig|cow|ape|bee|eel|emu|fox|elk|yak|ram|bug|cub|pup/.test(w)&&!/^(cats?|dogs?|ants?|rats?|bats?|owls?|hens?|pigs?|cows?|apes?|bees?|eels?|emus?|fox|foxes|elks?|yaks?|rams?|bugs?|cubs?|pups?)$/.test(w)},3);
  WL('w_number',function(w){return w.length>=4&&/one|two|three|four|five|six|seven|eight|nine|ten/.test(w)&&!/^(one|two|three|four|five|six|seven|eight|nine|ten)s?$/.test(w)},3);
  WL('w_isogram',function(w){if(w.length<9)return false;var s={};for(var i=0;i<w.length;i++){if(s[w[i]])return false;s[w[i]]=1}return true});
  WL('w_onevowel',function(w){var v=w.match(VOW);return w.length>=7&&!!v&&v.length===1&&!/y/.test(w)});
})();
